INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000000148', 'radical', '矛', 'spear', 21, 3, 'Ibumu membawa semacam senjata rumit. Anda melihat lebih dekat dan melihat bahwa itu adalah tombak. Ujungnya yang lancip ada di sebelah kanan, dan ada beberapa hiasan yang menggantung di sana. Itu tombak yang sangat mewah, dan kamu bertanya-tanya dari mana ibumu mendapatkannya.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000162', 'radical', '片', 'one-sided', 30, 0, 'Ini terlihat seperti seorang pelayan yang berjalan ke arah Anda dengan piring di tangannya... tapi tunggu. Itu hanya setengah dari seorang pelayan. Itu adalah pelayan satu sisi!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000276', 'radical', '啇', 'mohawk', 21, 0, 'Ada sesuatu yang lama di kepalamu yang sedang berdiri. Benda apa ini? Mohawk yang mengagumkan. Anda sudah memilikinya begitu lama sehingga terlihat cukup tua... tapi masih mengagumkan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000277', 'radical', '斉', 'simultaneous', 21, 1, 'Jika Anda menulis sambil melihat ke bulan, bisa dipastikan orang lain juga melakukannya. Orang mempunyai kebiasaan memandang bulan secara bersamaan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000278', 'radical', '次', 'next', 21, 2, 'Radikal ini sama dengan kanji. Artinya selanjutnya.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000279', 'radical', '平', 'peace', 21, 3, 'Radikal ini sama dengan kanji. Artinya perdamaian.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000280', 'radical', '番', 'number', 21, 4, 'Radikal ini sama dengan kanji, namun "angka dalam satu rangkaian" terlalu panjang. Mari kita persingkat menjadi angka.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000281', 'radical', '角', 'angle', 21, 5, 'Radikal ini sama dengan kanji. Artinya sudut.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000282', 'radical', '呂', 'bathtub', 22, 0, 'Lihat pria yang duduk di dalam kotak? Kepalanya mencuat keluar dari atas. Itu bak mandi yang dia duduki.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000283', 'radical', '安', 'cheap', 22, 1, 'Radikal ini sama dengan kanji. Artinya murah.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000284', 'radical', '弗', 'dollar', 22, 2, 'Ini adalah coretan dengan dua garis melewatinya. Hmmm sepertinya familiar bukan? Seharusnya, karena itu simbol dolar: $. Yah, cukup dekat. Lihat saja ini dan pikirkan, ah ya, dolar Amerika yang normal.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000285', 'radical', '充', 'allocate', 22, 3, 'Anda memiliki beberapa kaki dan Anda harus membuangnya ke tempat sampah. Namun Anda akan ketahuan jika memasukkannya ke dalam satu tempat sampah. Cepat, potong dan buang ke tempat sampah lain di sekitar kota. Maka Anda tidak akan pernah tertangkap.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000286', 'radical', '爰', 'football', 22, 4, 'Teman Anda tergeletak di tanah dan Anda menginjaknya dengan gerigi sepatu Anda. Tidak ada persahabatan di sini. Ini adalah olahraga sejati yang Anda mainkan. Inilah sepak bola.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000287', 'radical', '能', 'ability', 22, 5, 'Radikal ini sama dengan kanji. Artinya kemampuan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000288', 'radical', '革', 'leather', 23, 0, 'Ketika saya melihat radikal ini, saya melihat tubuh dan (terutama) kepala seekor banteng. Banteng terbuat dari apa? Mereka terbuat dari kulit.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000289', 'radical', '丩', 'vines', 23, 1, 'Radikal ini terdiri dari dua tanaman merambat yang menjuntai ke bawah dan sebuah cabang yang menghubungkan keduanya. Bayangkan berayun dengan gaya Tarzan ini. AaaaAA aAA AAAaaaa!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000290', 'radical', '亭', 'restaurant', 23, 2, 'Anda melihat tutup di jalan dengan gambar dahi dan mulut di atasnya. Hmm aneh. Anda membuka tutupnya dan mengungkap... sebuah restoran rahasia bawah tanah! Kombo mulut + dahi adalah kode rahasia restoran jalanan untuk, "Ada makanan enak di lubang restoran ini!"', NULL, NULL),
  ('00000000-0000-4000-8000-000000000291', 'radical', '道', 'road', 23, 3, 'Radikal ini sama dengan kanji. Artinya jalan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000292', 'radical', '鬼', 'demon', 23, 4, 'Ini adalah setan. Bisakah kamu melihatnya? Dia memiliki wajah gila dan beberapa tentakel memegang sesuatu yang jahat. Cobalah mencari cara untuk melihat setan. Tapi jangan melihatnya terlalu bagus, karena dia akan keluar dari komputer Anda dan memakan Anda.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000293', 'radical', '旦', 'dawn', 24, 0, 'Matahari terbit dari bawah tanah, membuat fajar yang radikal ini. Tentu saja, jangan bingung membedakannya dengan senja! Hal itu bisa dilakukan dengan berpikir bahwa matahari adalah sesuatu yang optimis dan cerah, sehingga cenderung terbit, bukan terbenam. (Juga, Jepang adalah Negeri Matahari Terbit. Maksudku, ayolah!)', NULL, NULL),
  ('00000000-0000-4000-8000-000000000294', 'radical', '韋', 'korea', 24, 1, 'Ada lima mulut yang memakan sapi di Korean BBQ. Korea terkenal dengan BBQnya yang lezat, dan Anda membutuhkan banyak orang untuk memakan semua daging sapi tersebut. Setidaknya lima orang. (Paham? Lima orang!) Itu sebabnya yang radikal ini adalah Korea.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000295', 'radical', '客', 'guest', 24, 2, 'Radikal ini sama dengan kanji. Artinya tamu.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000296', 'radical', '制', 'control', 24, 3, 'Radikal ini sama dengan kanji. Artinya kendali.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000297', 'radical', '然', 'nature', 24, 4, 'Radikal ini sama dengan kanji. Artinya alam.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000298', 'radical', '受', 'accept', 24, 5, 'Radikal ini sama dengan kanji. Artinya menerima.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000299', 'radical', '京', 'capital', 25, 0, 'Radikal ini sama dengan kanji. Artinya modal.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000300', 'radical', '甫', 'wedding', 25, 1, 'Radikal ini terlihat seperti seseorang yang mengenakan gaun raksasa yang meneteskan air mata. Ini adalah seseorang di pernikahan mereka. Hal ini menjelaskan gaun besar dan air mata (kebahagiaan!) di mata mereka.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000301', 'radical', '友', 'friend', 25, 2, 'Radikal ini sama dengan kanji. Artinya teman.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000302', 'radical', '交', 'mix', 25, 3, 'Radikal ini sama dengan kanji. Artinya campur aduk.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000303', 'radical', '冓', 'lifeguard', 25, 4, 'Anda memiliki tugas untuk menyelamatkan dua jenis nyawa. Siapa yang menyelamatkan dua jenis nyawa? Seorang penjaga pantai. Mereka menyelamatkan nyawa orang-orang yang tenggelam, dan kemudian nyawa orang-orang yang mencoba menolong mereka. Bayangkan seorang penjaga pantai menyelamatkan nyawa dua orang sekaligus. Pahlawan yang luar biasa!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000304', 'radical', '両', 'both', 25, 5, 'Radikal ini sama dengan kanji. Artinya keduanya.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000305', 'radical', '半', 'half', 21, 6, 'Radikal ini sama dengan kanji. Artinya <radikal>setengah</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000306', 'radical', '告', 'announce', 26, 0, 'Radikal ini sama dengan kanji. Artinya mengumumkan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000307', 'radical', '万', 'ten-thousand', 26, 1, 'Radikal ini sama dengan kanji. Artinya sepuluh ribu.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000308', 'radical', '農', 'farming', 27, 0, 'Radikal ini sama dengan kanji. Artinya bertani.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000309', 'radical', '而', 'rake', 27, 1, 'Jika Anda melihatnya, Anda dapat melihat bahwa itu adalah penggaruk yang terlihat aneh.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000310', 'radical', '代', 'substitute', 27, 2, 'Radikal ini sama dengan kanji. Artinya <radikal>pengganti</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000311', 'radical', '化', 'change', 27, 3, 'Radikal ini sama dengan kanji. Artinya <radikal>perubahan</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000312', 'radical', '民', 'peoples', 27, 4, 'Radikal ini sama dengan kanji. Artinya masyarakat.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000313', 'radical', '余', 'surplus', 27, 5, 'Radikal ini sama dengan kanji. Artinya surplus.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000314', 'radical', '巨', 'giant', 28, 0, 'Jika Anda melihat raksasa dari atas, inilah yang akan Anda lihat. Apakah Anda melihat kepala dan kedua lengan? Raksasa itu menghadap ke arah kanan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000315', 'radical', '屯', 'barracks', 28, 1, 'Anda menempelkan payung dengan perosotan besar ke lereng gunung untuk membuat barak Anda. Anda akan menggunakan barak ini untuk mengajari tentara cara meluncur dan bersembunyi dari cuaca buruk. Itu cerdik!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000316', 'radical', '絜', 'hercules-316', 28, 0, 'Benang kehidupan dipotong dengan pedang oleh Moirai. Mereka, dalam mitologi Yunani, adalah orang-orang yang memutuskan kapan akan membiarkan Anda mati, dengan memotong benang kehidupan Anda. Hal ini mungkin paling terkenal dalam kisah Hercules, jadi kita akan membahasnya secara radikal.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000317', 'radical', '専', 'specialty', 28, 2, 'Radikal ini sama dengan kanji. Artinya spesialisasi.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000318', 'radical', '麗', 'lovely', 28, 3, 'Aku tidak tahu benda apa ini, tapi ini indah. Ia memiliki dua mata, mulut yang lucu, dan janggut yang kurus. Itu indah, dan tidak ada yang lain, oke? Jadi ingatlah seperti itu.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000319', 'radical', '尞', 'charcoal', 29, 0, 'Saat matahari mulai kecil, Anda perlu memanaskannya dengan melemparkan beberapa tanduk besar ke dalam api. Ini berubah menjadi arang. Arang yang enak dan hangat yang membuat Anda tetap hangat saat matahari mulai terbenam.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000320', 'radical', '衣', 'clothes', 23, 5, 'Anda membuka tutup kotak. Di dalam kotak itu ada sekumpulan pakaian. Radikal ini akan sama dengan kanji yang akan Anda pelajari nanti, jadi akan sangat membantu jika mempelajarinya sebagai pakaian meskipun tidak terlihat seperti pakaian.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000321', 'radical', '責', 'blame', 29, 1, 'Radikal ini sama dengan kanji. Artinya menyalahkan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000322', 'radical', '区', 'district', 29, 2, 'Radikal ini sama dengan kanji. Artinya distrik.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000323', 'radical', '臣', 'servant', 29, 3, 'Hei, itu raksasa yang kamu pelajari sebelumnya. Tapi... tapi lengannya dirantai. Mereka dirantai karena kamu menangkap raksasa itu dan sekarang dia menjadi pelayanmu!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000324', 'radical', '乙', 'nose', 29, 4, 'Jika Anda melihat ke kanan radikal ini, Anda akan melihat HIDUNG (dengan mata sipit di sebelah kiri).', NULL, NULL),
  ('00000000-0000-4000-8000-000000000325', 'radical', '上', 'above', 29, 5, 'Radikal ini sama dengan kanji. Artinya di atas.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000326', 'radical', '奇', 'odd', 28, 4, 'Cincin bibir yang besar adalah hal yang cukup aneh untuk dimiliki. Kalau besar, bibirmu akan melebar, dan itu aneh juga.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000327', 'radical', '北', 'north', 30, 1, 'Radikal ini sama dengan kanji. Artinya <radikal>utara</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000328', 'radical', '監', 'oversee', 30, 2, 'Radikal ini sama dengan kanji. Artinya mengawasi.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000329', 'radical', '系', 'lineage', 30, 3, 'Seutas benang menembus tanah. Ini menelusuri garis keturunan Anda. Anda mengikuti alur cerita ini dari generasi ke generasi, untuk mengetahui bahwa garis keturunan Anda melibatkan Jenghis Khan. Rasakan benang dan kotoran di tangan Anda dan lacak garis keturunannya.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000330', 'radical', '甲', 'turtle-shell', 30, 4, 'Penyu yang malang. Kami tidak menyukai mereka di sini. Ini adalah cangkang kura-kura. Lihat cangkangnya yang hanya tersisa satu ekor? Itu satu-satunya hal yang tidak kami keluarkan dari penyu. Itu hanya cangkang yang berekor, jadi pada dasarnya itu hanyalah cangkang kura-kura.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000331', 'radical', '召', 'call', 27, 6, 'Jika seseorang menaruh pedang di mulutmu, kamu perlu berteriak minta tolong! Panggillah sekeras yang Anda bisa kepada siapa pun di dekat Anda yang mungkin dapat membantu Anda membuat orang ini mengeluarkan pedang dari mulut Anda.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000332', 'radical', '出', 'exit', 27, 7, 'Radikal ini sama dengan kanji. Artinya keluar.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000356', 'radical', '莫', 'greenhouse', 25, 6, 'Bunga membutuhkan sinar matahari untuk menjadi besar. Untuk membantu mereka tumbuh sebesar mungkin, kami menaruhnya di rumah kaca.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000391', 'radical', '冘', 'pirate', 30, 5, 'Ini terlihat seperti besar (大), yang menurut saya Anda akan ingat bahwa Anda mempelajarinya dengan berpura-pura ini adalah orang besar. Namun pria besar ini mempunyai kaki yang lucu... kaki pasak. Itu membuatnya menjadi bajak laut. Selain itu, lengannya berada pada posisi "YARRRR".', NULL, NULL),
  ('00000000-0000-4000-8000-000000000393', 'radical', '刃', 'blade', 21, 7, 'Anda memiliki pedang yang ada setetes sesuatu di atasnya. Tetesan itu adalah setetes darah. Tentu saja, pedang akan memotong seseorang hingga menumpahkan darah, tetapi yang Anda perlukan hanyalah pisau apa pun untuk memotong seseorang. Pedang, pisau, apa saja, asalkan bilahnya.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000425', 'radical', '禹', 'mantis', 25, 7, 'Radikal ini memiliki slide, kepala, dan serangga di dalamnya. Serangga manakah yang akan memenggal kepala Anda dalam hitungan detik dan kemudian memakannya? Belalang sembah yang menakutkan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000001123', 'kanji', '敵', '敵', 21, 8, 'Seeing a mohawk in the winter means the enemy is nearby. You are from the dreadlock tribe and the mohawk tribe is your enemy. You’re deep in the heart of battle and winter has fallen. Now is the time to take out the enemy.', 'You’re kind of a techie (てき), so you have an advantage over your enemy. You’re armed with night vision goggles and other cool tech gear as well. Being a techie certainly has its advantages.', NULL),
  ('00000000-0000-4000-8000-000000001124', 'kanji', '済', '済', 21, 9, 'You see a tsunami that''s simultaneous (with another tsunami, I assume) and you know the world is about to come to an end.', 'Just as the world is about to come to an end, your cyborg (さい) appears and blocks it with its cyborg body!', NULL),
  ('00000000-0000-4000-8000-000000001125', 'kanji', '委', '委', 21, 10, 'Women who get together to talk about grains are a committee. They''re the Committee of Women for Grains (tm tm tm). What does this committee discuss, you wonder.', 'Well, grains need a committee because the eagles (い) have been eating them all. The women know this, so they''re meeting and trying to come up with a way to stop these pesky eagles from eating all the grains and leaving none for the humans.', NULL),
  ('00000000-0000-4000-8000-000000001126', 'kanji', '挙', '挙', 21, 11, 'If there’s grass on the ground and fins in your hand, you need to raise that hand up to the sky. You’re in the middle of a fisherman’s ritual, which can only be performed on grassy ground. You take fish fins from the previous year, and raise them up to the sky in order to ensure a good fishing harvest.', 'This ritual only works in one part of the world however. It absolutely must be performed in Little Kyoto (きょ). The way Little Kyoto lines up with the sun and the sky and all that astrological junk makes it the best place for you to raise fish fins up in the air.', NULL),
  ('00000000-0000-4000-8000-000000001127', 'kanji', '判', '判', 21, 12, '"I''ll cut that baby in half with a knife if you don''t figure out custody," says the judge. Ah, the oldest judge trick in the book.', 'This judge is Han (はん) Solo, so you know he''s not going to back down.', NULL),
  ('00000000-0000-4000-8000-000000001128', 'kanji', '制', '制', 21, 13, 'Cows, using nothing more than towels and knives, have taken control of the world. Their system of control is brutal—payback for how us humans have treated them I guess.', 'It''s time to take control back from the cows! Pull out your saber (せい) and fight back!', NULL),
  ('00000000-0000-4000-8000-000000001129', 'kanji', '務', '務', 21, 14, 'You use a special spear in winter to give yourself the power to do all of your tasks.', 'Your task is to spear this cow. "Moo (む)!" it yells at you and runs away. You need to make dinner though... that''s your task, so you better catch up to that cow and put an end to its mooing.', NULL),
  ('00000000-0000-4000-8000-000000001130', 'kanji', '査', '査', 21, 15, 'If a tree is growing out of a top hat you need to inspect it to find out why and how this happened. You should probably investigate the area too. I mean, how could a tree grow out of a top hat anyway? Seems suspicious.', 'In the middle of your inspection you realize you need to saw (さ) the tree open to come to a good conclusion. This seems a bit unnecessary, but no! No! For the sake of this investigation you must saw the tree in half!', NULL),
  ('00000000-0000-4000-8000-000000001131', 'kanji', '総', '総', 21, 16, 'Taking out your thread, you sew together the public''s hearts to make them whole again.', 'Once their hearts are whole, the public''s soul (そう) becomes one!', NULL),
  ('00000000-0000-4000-8000-000000001132', 'kanji', '設', '設', 21, 17, 'If you say a new weapon idea out loud, then it will be established immediately.', 'Weapons have to be established in sets (せつ). So you have to make another one that goes with it. Make them cohesive please.', NULL),
  ('00000000-0000-4000-8000-000000001133', 'kanji', '資', '資', 21, 18, 'The next shellfish will be yours, but this shellfish will be mine. These are the resources we have to share and distribute.', 'You save up all of your resources so you can buy a sheep (し). You bring a big sack of your shellfish resources to the market and finally get to pick out that sheep you''ve had your eyes on for months.', NULL),
  ('00000000-0000-4000-8000-000000001134', 'kanji', '権', '権', 21, 19, 'Under the tree lies a turkey with a broken arrow in it. It doesn''t have rights like humans, so people can just shoot turkeys with arrows and no one is punished.', '"You have rights, so I won''t shoot you like this turkey," says the voice of Ken (けん) the samurai, from above you in the tree.', NULL),
  ('00000000-0000-4000-8000-000000001135', 'kanji', '件', '件', 21, 20, 'The leader of the cow tribe is too important to deal with small matters and trivial affairs.', 'All of his affairs are taken care of by Ken (けん) the samurai, who he hired as his underling.', NULL),
  ('00000000-0000-4000-8000-000000001136', 'kanji', '派', '派', 21, 21, 'A tsunami is coming for the cliff made of tofu, but there is a special sect that protects tofu cliff.', 'All of the members of the sect are standing on the cliff, their hands raised, and right as the tsunami is about to collide with them, they shout, "Ha (は)!" and it''s repelled! The tsunami sinks and rolls back out to sea, the tofu cliff is safe!', NULL),
  ('00000000-0000-4000-8000-000000001137', 'kanji', '岡', '岡', 21, 22, 'You have a scene going on inside your head. It is of a pair of horns on the ground atop a mountain. No. It is not just one pair of horns. It is many. So many that they create a giant hill atop the mountain, which is already pretty high.', 'How was standing atop this hill of horns on top of a mountain to touch the sky? Eh. It was okay (おか), but that''s about it.', NULL),
  ('00000000-0000-4000-8000-000000001138', 'kanji', '素', '素', 21, 23, 'The life thread is an element essential to all living things. This thread of life joins all things together, providing an essential relationship between all life. This element is all that holds this world together.', 'You need to keep this element clean, so you make sure to wash it with soap (そ) every single day. This turns out to be pretty hard because the element is an invisible thread, but you do your best.', NULL),
  ('00000000-0000-4000-8000-000000001139', 'kanji', '断', '断', 21, 24, 'A lion harvesting rice uses an axe to cut off the tops of the stalks. The lion is roaming the rice fields using his axe to harvest the rice. He does so by cutting off the part of the rice stalks he needs.', 'The lion will cut off rice stalks until dawn (だん). But at the first light of dawn, it will run and hide in the shade of the trees, cut off from the rice.', NULL),
  ('00000000-0000-4000-8000-000000001140', 'kanji', '評', '評', 21, 25, 'You should say "peace" before you evaluate a situation. That way everyone will know where you’re coming from. If you’re honest and say "peace" before you evaluate a situation out loud, everyone will know where you stand.', 'When you say "peace," you end up making a really bad pun and you hear somebody say “Heyo!” (ひょう) You look at the people around you and try to evaluate who said heyo, but you can’t tell. You start talking again when somebody exclaims “That’s what she said” and another person shouts “Heyo!” once again, but you still can’t evaluate who’s saying these things.', NULL),
  ('00000000-0000-4000-8000-000000001141', 'kanji', '批', '批', 21, 26, 'If you use your fingers to point when you compare things you''re really just throwing around criticism. You should never need to point fingers when you''re just comparing things. If you''re pointing and picking and being mean, that''s criticism.', 'If you''re having trouble not giving out criticism, just think about how you would react if someone criticized you. You''d feel an embarrassed heat (ひ) rise throughout your body. That heat will cover your whole face.', NULL),
  ('00000000-0000-4000-8000-000000001142', 'kanji', '任', '任', 21, 27, 'Both a leader and a king have a duty to protect their people. A good leader always protects his followers, and a good king always protects his subjects. This is their duty.', 'You’re the village nincompoop (にん), but the king and the leader still have a duty to protect you. Even a nincompoop is important to the kings and leaders of the world.', NULL),
  ('00000000-0000-4000-8000-000000001143', 'kanji', '検', '検', 21, 28, 'You see a tree with a squid on it, so you get closer to examine it.', 'You''re sticking your face in really, really close to examine this little squid in the tree when Ken (けん) the samurai appears behind you. "There you are, squid! Thank you citizen, I''ve been looking all over for my little chum."', NULL),
  ('00000000-0000-4000-8000-000000001144', 'kanji', '審', '審', 21, 29, 'You''re about to enter a roof that has your number on it so you can face the judge. You''ve been sitting here for what feels like hours, waiting for your number to come up. Finally the time has come—the judge will see you now.', 'The judge is not happy with you. He tells you to come closer and when you do, he takes his gavel and hits you in the shins (しん). Ouch!', NULL),
  ('00000000-0000-4000-8000-000000001145', 'kanji', '条', '条', 21, 30, 'A winter tree is only a winter tree due to a clause in its tree contract.', 'This clause was written into all trees'' contracts by Jourm (じょう), the large farmhand.', NULL),
  ('00000000-0000-4000-8000-000000001146', 'kanji', '責', '責', 21, 31, 'The life of a shellfish is filled with blame. They take the blame for everything from food poisoning and allergies, to cutting people''s feet on beaches.', 'When those poor shellfish aren''t having blame piled on them, they''re being eaten, because shellfish are thought to make for a very sexy (せき) meal.', NULL),
  ('00000000-0000-4000-8000-000000001147', 'kanji', '省', '省', 21, 32, 'You only have a few eyes so you need to conserve what''s left.', 'You''re trying to conserve your eyes, when the Shougun (しょう) marches by. He stops, sees you, and demands you give him your remaining eyes! But sir, I''m conserving what little I have left!', NULL),
  ('00000000-0000-4000-8000-000000001148', 'kanji', '増', '増', 21, 33, 'The dirt mask is a mask which, when put on, will greatly increase the amount of dirt.', 'Use the dirt mask to increase the dirt around you. The zombies (ぞう) are trying to escape, so you just keep increasing the dirt on top of them so they can''t get out.', NULL),
  ('00000000-0000-4000-8000-000000001149', 'kanji', '税', '税', 21, 34, 'A guard is at your door and wants some of your grains. This is the tax you pay for living in this town. Back in the day, grains were used like currency, so it makes sense that there was a grain tax in the olden days.', 'You have to pay this tax, because if you don''t the guard will cut you down with his special German saber, a zeiber (ぜい). "Don''t you hear vat I zei? Pay ze tax or I vill zlei you!" he shouts.', NULL),
  ('00000000-0000-4000-8000-000000001150', 'kanji', '解', '解', 21, 35, 'Angle your sword correctly at a cow to untie it without hurting it. This is actually a pretty tough angle to get your sword, so in order to solve this cow puzzle you have to be really smart and careful.', 'You''re trying to untie this cow from the kayak (かい) you''re both currently in. Some jerk tied the cow to this kayak and sent it toward a waterfall. If you don''t solve this riddle fast, you''ll both go with the kayak over the falls!', NULL),
  ('00000000-0000-4000-8000-000000001151', 'kanji', '際', '際', 21, 36, 'Buildings hold festivals on special occasions.', 'The occasion this time is to celebrate your wonderful cyborg (さい). It''s about time you did something nice for it.', NULL),
  ('00000000-0000-4000-8000-000000001152', 'kanji', '認', '認', 21, 37, 'What people say to you will be carved by a blade into your heart, and the next time you see them, you''ll immediately recognize them.', 'You recognize places, names, and even games this way. But the thing that has the most real estate on your heart, the thing you recognize the most, is Nintendo (にん).', NULL),
  ('00000000-0000-4000-8000-000000001153', 'kanji', '企', '企', 21, 38, 'The hat comes to a stop, thinking of a plan. The hat had been pacing around for a while, trying to think of how to get off the head he''s resting upon and back into the house where it''s nice and cozy, and came to the sudden realization of a plan. This caused the hat to stop.', 'The plan that made this hat stop right in its tracks was very simple. First, obtain the key (き) to the house. Then, use the key to get in the front door. How simple!', NULL),
  ('00000000-0000-4000-8000-000000001154', 'kanji', '義', '義', 21, 39, 'The kanji and the radical are exactly the same. That means they share meanings as well.', 'Such righteousness! Well, at least according to the king who thinks he''s being righteous. His version of righteousness is to send anyone who disagrees with him to the guillotine (ぎ).', NULL),
  ('00000000-0000-4000-8000-000000001155', 'kanji', '罰', '罰', 22, 7, 'If you try to say things with a knife, the police will put you in a net as your penalty for breaking the knife laws. You can''t just go up to other people and say things with a knife out.', 'Your penalty for breaking the law isn''t over. Now that you''re stuck in a net, you can''t fight back when they hit you with bats (ばつ).', NULL),
  ('00000000-0000-4000-8000-000000001156', 'kanji', '誕', '誕', 22, 8, 'They say yoga is the correct way to go through birth. Birth isn''t easy, but people keep telling you that yoga is the right way to prepare and actually do it.', 'To prepare for giving birth you end up doing so much yoga outside that you get a really deep tan (たん).', NULL),
  ('00000000-0000-4000-8000-000000001157', 'kanji', '脱', '脱', 22, 9, 'The light of the moon is shining on a guard who''s been on duty all night. The moon light makes him so warm and comfortable that he forgets where he is and starts to undress. He thinks he''s home! Everyone is going to see him take off his clothes!', 'You can''t seem to get the guard to stop undressing so you throw some darts (だつ) at him. You figure that even if the guard doesn''t snap out of this weird sleepy trance, at least you can use the darts to stick his clothes to his body. Then maybe he won''t be able to undress anymore.', NULL),
  ('00000000-0000-4000-8000-000000001158', 'kanji', '過', '過', 22, 10, 'While riding on your scooter, you grow a mustache on top of the mustache you already have in order to surpass the people around you. You''re in a scooter race and your mustache is the only thing keeping you in the lead, but someone else has a mustache too! So you grow another mustache to surpass them once again!', 'Suddenly, something else manages to surpass you all. It''s a car (か)! A car with two mustaches is also riding on a scooter and going way faster than you.', NULL),
  ('00000000-0000-4000-8000-000000001159', 'kanji', '坊', '坊', 22, 11, 'Can you look at the dirt and know which direction you need to go? Then you might be a monk. Monks have amazing skills like that. And I''m sure you''ve seen monks wandering around in lots of media. They don''t need maps or smartphones. They just look at the dirt and let the earth guide them to where they need to be.', 'You want to know the monk''s trick so you hide behind him for a while as he walks. Finally the monk stops, looks around, takes out a bowling (ぼう) ball and starts bowling in the dirt. The bowling ball rolls off, the monk follows it, and then heads off in that direction.', NULL),
  ('00000000-0000-4000-8000-000000001160', 'kanji', '寝', '寝', 22, 12, 'From the roof, an icicle falls and hits wolverine in the forehead, and he has to go over to the stool to lie down. And eventually he goes to sleep.', 'While wolverine sleeps, he makes a horrible neighing (ね) sound. It''s like there''s a giant horse in his mouth screaming to get out! NEIGH NEIGH!', NULL),
  ('00000000-0000-4000-8000-000000001161', 'kanji', '宮', '宮', 22, 13, 'It may just be a roof over a bathtub, but this here is actually a Shinto shrine.', 'What god does this Shinto shrine hold? You see that "It''s a-me-ya! (Mario!)"', NULL),
  ('00000000-0000-4000-8000-000000001162', 'kanji', '各', '各', 22, 14, 'You kiss each of your best pals to show them how much you love and care for them. You kiss each friend right on the mouth.', 'Actually, each of your best pals are of the cock (かく) variety. By that, I mean they are both roosters. Imagine kissing both of these cocks on their beaks.', NULL),
  ('00000000-0000-4000-8000-000000001163', 'kanji', '案', '案', 22, 15, 'A cheap tree has a plan. A plan to stay cheap.', 'The cheap tree''s plan involves only buying anchovies (あん) and surviving on them. Good exposure to the sun and fresh water is too expensive. The tree plans to save money by eating anchovies.', NULL),
  ('00000000-0000-4000-8000-000000001164', 'kanji', '置', '置', 22, 16, 'This net needs to be fixed if you want to put food on the table.', 'Once it''s fixed, you put a bunch of cheese (ち) in the net. You want to catch something that eats cheese, so that you can then put that animal on your dinner table.', NULL),
  ('00000000-0000-4000-8000-000000001165', 'kanji', '費', '費', 22, 17, 'Dollars and shellfish are used to pay expenses and costs. Shellfish used to be used as currency, so they''re like the coins that go with dollars.', 'What is the biggest expense and cost? It''s the heat (ひ) bill.', NULL),
  ('00000000-0000-4000-8000-000000001166', 'kanji', '価', '価', 22, 18, 'The helicopter the leader is in has the most value! He would only choose to fly the very best one, after all. That''s why it''s worth way more than the others. Actually, any helicopter he flies goes up in value. That''s the amazing effect of a good leader.', 'To further increase the helicopter''s value, the leader bought himself a car (か) and then tied them together. Now it has the value of a helicopter AND a car! Wow!', NULL),
  ('00000000-0000-4000-8000-000000001167', 'kanji', '勢', '勢', 22, 19, 'The womb is a circle of power where a force of nature is formed. The womb has the power to create life. Life is a force of nature, and the circle of life starts in the womb.', 'Now pretend you''re the mother. You''ll need all the force you can muster to bring that baby into the world, so you grab hold of your special saber (せい) and slice it about in the air to give you the extra force you need.', NULL),
  ('00000000-0000-4000-8000-000000001168', 'kanji', '営', '営', 22, 20, 'A Viking who knows how to use a bathtub will have to manage all the baths for the other Vikings. Vikings aren''t so great with bathing... if you can get one Viking to figure it out he has to manage the rest of them.', 'The poor Viking trying to manage all the others keeps having to confiscate acorns (えい). "You can''t take baths in acorns and wood, it has to be water!" he shouts.', NULL),
  ('00000000-0000-4000-8000-000000001169', 'kanji', '示', '示', 22, 21, 'You can use a jackhammer to indicate and show someone where the prize is buried. You buried the prize to keep it safe, but the jackhammer is great at unearthing it. Jackhammers do a great job and show where the treasure lies. They indicate quite clearly where one needs to go.', 'Actually, you''re unearthing Jesus (じ). He’s the treasure. For your soul. He’s here to show you that Jesus is still a hip and cool guy and he wants to indicate to you that having faith in Jesus and God and stuff is super rad. Jesus is all like, “Who has two thumbs and wants to show you the way of the Lord? This guy.”', NULL),
  ('00000000-0000-4000-8000-000000001170', 'kanji', '統', '統', 22, 22, 'You take all of your thread and allocate them into one place to unite them. With all your thread united and wrapped together, you''re ready to rule and govern the world!', 'You''re busy trying to unite all of your thread, twisting and tying and wrapping, and suddenly you look at the ball in your hands and see とうきょう. You''ve united this thread into the shape of とうきょう. There are even little pins for all the famous neighborhoods and tourist spots. This is strange, because you don''t remember putting them there.', NULL),
  ('00000000-0000-4000-8000-000000001171', 'kanji', '領', '領', 22, 23, 'Taking orders from a geoduck will place you into enemy territory. Geoducks make terrible commanders, so if you take orders from one, expect to end up in unknown territory, potentially even enemy territory. Be prepared.', 'Not wanting to end up dead in enemy territory, you decide to escape this geoduck leader by getting on a row (りょう) boat and rowing your way outta there. The geoduck commander orders you to halt your escape, but you still get in your row boat and row away.', NULL),
  ('00000000-0000-4000-8000-000000001172', 'kanji', '策', '策', 22, 24, 'With a bamboo tree resting atop your head, you devise a plan. The plan is actually for getting the bamboo tree off of your head. You’re trapped under it.', 'But why is this bamboo tree so heavy? You look to each end of the bamboo and realize that there is a sack (さく) tied on each end. Each sack seems to be filled with heavy rocks. Looks like someone made a plan to trap you here. Now you have to devise a plan to escape!', NULL),
  ('00000000-0000-4000-8000-000000001173', 'kanji', '藤', '藤', 22, 25, 'The only flowers that the moon gladiators will water are wisteria.', 'Since they''re on the moon, where did they get the wisteria from? Actually, from one of the points on earth that is nearest to the moon, Mt. Fuji (ふじ).', NULL),
  ('00000000-0000-4000-8000-000000001174', 'kanji', '副', '副', 22, 26, 'That scarecrow with the knife is the vice president. Yeah, I know how he looks, and I''m pretty sure he does some murdering on the side, but you didn''t hear that from me.', 'It''s the vice president''s turn to speak at the podium and he just clears his throat and yells, "F**k (ふく) you!" to the crowd, holding up his knife. They cheer.', NULL),
  ('00000000-0000-4000-8000-000000001175', 'kanji', '観', '観', 22, 27, 'There''s an arrow in a turkey that you can see in your view. The turkey seems to be viewing you too, from afar.', 'As you view the turkey, Genghis Khan (かん) suddenly comes into your view too. He towers over the injured turkey, leans down, and... pulls the arrow out!?', NULL),
  ('00000000-0000-4000-8000-000000001176', 'kanji', '値', '値', 22, 28, 'A leader can fix the value of certain goods and services. Leaders basically get to decide how much everything is worth in value, like rice or lamps or how much you get paid for the work you do.', 'This leader has fixed the value of cheese (ち), making it ￥1 permanently. One yen! That''s, like, less than a penny! Unfortunately, the leader won''t fix any of the other really expensive things... so now everyone only eats cheese.', NULL),
  ('00000000-0000-4000-8000-000000001177', 'kanji', '吸', '吸', 22, 29, 'Your mouth is like an escalator you use to suck and inhale things into your body.', 'Use this mouth ability to suck cucumbers (きゅう) into your mouth. Cucumbers are shaped like cylinders so you can suck them into your mouth like this. Just as nature intended.', NULL),
  ('00000000-0000-4000-8000-000000001178', 'kanji', '域', '域', 22, 30, 'Under the dirt in the ground is a drunkard with something in his mouth from a region in North America. He died from whatever it is that’s in his mouth. That’s how this drunkard ended up under the ground in the first place. His whole face region is disfigured from whatever he ate. I wonder what region of North America the strange object came from?', 'In an attempt to identify what region of North America the thing in the drunkard’s mouth came from, you touch it and try to remove it with your bare hands. Upon touching whatever it is, you find it to be all icky (いき) and gooey. Like, super icky. So icky that you barf in the region immediately adjacent to you.', NULL),
  ('00000000-0000-4000-8000-000000001179', 'kanji', '姿', '姿', 22, 31, '“Bring in the next woman so that I may examine her figure!” We’re holding auditions for a commercial and we need to find a woman with a nice figure. The last woman was no good, so bring in the next one.', 'The next woman comes in and you examine her figure. The figure you''ve been searching for! It just happens to belong to a sheep (し) woman. But she''s soft, fluffy, and round. The perfect figure!', NULL),
  ('00000000-0000-4000-8000-000000001180', 'kanji', '応', '応', 22, 32, 'If someone gets under the canopy over your heart you should respond to them.', 'You respond and it turns out it was to the 王 (おう).', NULL),
  ('00000000-0000-4000-8000-000000001181', 'kanji', '提', '提', 22, 33, 'Pointing your fingers to the sun is the correct way to present yourself or offer to submit your ideas. You''re really just raising your hand. And when you want to present yourself, your ideas, or offer anything, the correct way is to raise your fingers to the sun. You definitely learned this in school.', 'You want to present your show and tell of tater tots (てい) to the class. You raise your hand, the teacher calls on you, and you submit the tater tots for her and the class''s approval. "Oh my!" the teacher exclaims, "I hope you brought enough tater tots to present to the whole class!" You raise your hand once more to the sky, and in it you submit a whole tray of tater tots!', NULL),
  ('00000000-0000-4000-8000-000000001182', 'kanji', '援', '援', 22, 34, 'You use your fingers in the game of football to aid and assist the other players. And when you smash your fingers in football, you need to get some aid yourself.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000001260', 'kanji', '逮', '逮', 25, 20, 'Your scooter''s been stolen by a wolverine, who''s now getting water all over it. You need to apprehend that wolverine!', 'You catch up with the wolverine and apprehend it by tying it down with the tie (たい) from around your neck!', NULL),
  ('00000000-0000-4000-8000-000000001261', 'kanji', '補', '補', 25, 21, 'There is a spirit at your wedding. It''s there as a supplement to the guests because not enough people came.', 'Along with the spirits to supplement your wedding guests, you made everyone carry a hoe (ほ). That way no one had to bring a date, they carry a garden hoe as a supplement and no one feels bad about being dateless. Everyone is!', NULL),
  ('00000000-0000-4000-8000-000000001262', 'kanji', '候', '候', 25, 22, 'A leader with a stick, a hook, and an arrow is able to change the climate and weather. Not just the type of climate that causes sunny and rainy days though, the political climate too, because they''re a political candidate too.', 'Who is this climate and weather-changing candidate leader with the hook, stick, and arrow? It''s none other than こういち.', NULL),
  ('00000000-0000-4000-8000-000000001263', 'kanji', '構', '構', 25, 23, 'A tree is what a lifeguard uses to set up the station where he''ll care for the people on the beach and in the water. Trees provide the shade lifeguards need to take care of half-drowned kids and grannies with sand stuck in their bathing suits. That''s why they set up their care stations here.', 'You look closer at the set up and realize the lifeguard is こういち! You know he teaches Japanese but... is こういち really qualified to care for people like this?', NULL),
  ('00000000-0000-4000-8000-000000001264', 'kanji', '模', '模', 25, 24, 'A tree grows next to a greenhouse enclosing an imitation of the tree. The imitation greenhouse tree wants to be big and impressive like the tree outside, so it does its very best imitation of a real tree.', 'The greenhouse tree realizes that its imitation will never be as good as the real thing. When it realizes this, the tree moans (も) aloud. The tree is still kinda tiny, so the moan isn’t very loud, but it is still pretty strange to witness. Speaking of witnesses, Bobo (ぼ) the clown sees this greenhouse tree moaning and decides to take it for his next clown show. Surely this miniature moaning tree can be worked into Bobo''s next clown act.', NULL),
  ('00000000-0000-4000-8000-000000001265', 'kanji', '捕', '捕', 25, 25, 'At your wedding you use your fingers to catch the wedding rings. And to catch the bouquet. And to catch the rice that everyone is throwing at you, ow, ow, hey stop! Weddings are really more about catching things than they are about whoever is standing across from you.', 'You''re having a good time catching things until it''s cleanup time and someone throws a hoe (ほ) at you. First of all, ow again, that was your face. Second, this is your wedding. You aren''t supposed to have to hoe it all up. You''re supposed to drop everything you caught and leave!', NULL),
  ('00000000-0000-4000-8000-000000001266', 'kanji', '鮮', '鮮', 25, 26, 'The fish and sheep are very fresh here. This is a great place to get fresh fish and fresh sheep. I kid you not.', 'This place also serves fresh centaur (せん), but that’s just weird. Centaur is endangered and you don’t believe in eating endangered things. Even if they are incredibly fresh.', NULL),
  ('00000000-0000-4000-8000-000000001267', 'kanji', '効', '効', 25, 27, 'If you mix different types of power you''ll produce something effective.', 'The most effective mix of two powers is two こういちs. Take one, mix it with another, and you have something with immeasurable power. You use it to attack that animal-like creature. It''s super effective!', NULL),
  ('00000000-0000-4000-8000-000000001268', 'kanji', '属', '属', 25, 28, 'You see a mantis sitting on a flag and you know for a fact that it does not belong there. Insects should be in trees and on the ground. Not on flags. Insects belong in the wild!', 'Luckily for you, and unluckily for this mantis who doesn''t belong on your flag, you''re a Bosozoku (ぞく) bike gang member, and you don''t take crap from nobody. You climb the flagpole, punch the mantis and yell, "YOU DON''T BELONG HERE!"', NULL),
  ('00000000-0000-4000-8000-000000001269', 'kanji', '慣', '慣', 25, 29, 'If you could just get your soul to open the window to shellfish, you''ll grow accustomed to them sooner or later! I know shellfish are a bit of an acquired taste, but if you don''t open that window, you''ll never like them!', 'You''ll need to become accustomed to eating shellfish if you want to grow up big and strong like Genghis Khan (かん). He didn''t have shellfish growing up either you know, he had to grow accustomed to their taste too, but look how successful he was!', NULL),
  ('00000000-0000-4000-8000-000000001270', 'kanji', '豊', '豊', 25, 30, 'Music beans make farts plentiful. And lucky for you, music beans themselves are also plentiful, so you can eat plenty of them to power your musical bean toots.', 'Your music bean farts are too plentiful to leave your home (ほう). If you tried to leave your home you''d definitely fart all over people outside, so you keep your plentiful farts to yourself.', NULL),
  ('00000000-0000-4000-8000-000000001271', 'kanji', '満', '満', 25, 31, 'If a tsunami hits these flowers they''ll both become full of water. Tsunamis carry a lot of water, definitely enough to make both of these flowers full.', 'As you stare at the full flowers, you decide to write a manga (まん) about them. Your head is full of manga ideas!', NULL),
  ('00000000-0000-4000-8000-000000001272', 'kanji', '肥', '肥', 25, 32, 'A moon who stays in bed all day every day will soon become obese. A healthy moon needs movement and exercise to stay fit and not become obese. If a moon stays in bed all day, they’ll be sure to grow obese over time.', 'Since the obese moon is in bed all day, and since the moon stays pretty cold, she needs some extra heat (ひ) to stay warm. A heated blanket should do the trick.', NULL),
  ('00000000-0000-4000-8000-000000001273', 'kanji', '巻', '巻', 25, 33, 'A gladiator only sees himself (oneself) on those big scrolls they advertise the fights with. Gladiators don''t get mirrors and there are no cameras or videos yet. The scroll drawings are all they get of themselves.', 'When you look at the scroll you realize... you look just like Genghis Khan (かん)! You excitedly fist pump and start showing everyone how cool you are.', NULL),
  ('00000000-0000-4000-8000-000000001274', 'kanji', '捜', '捜', 25, 34, 'You want to get your fingers on the humble stool, so you dedicate your life to search for it. Wait, the humble stool? You know, like the holy grail or the ark of the covenant, but it''s called the humble stool. It''s from some bible or something, I promise.', 'You search and you search and, unfortunately, you spend your entire life searching and you die without finding the humble stool. But don''t worry, your soul (そう) comes back and now you get to continue your search but with afterlife powers!', NULL),
  ('00000000-0000-4000-8000-000000001275', 'kanji', '絞', '絞', 25, 35, 'A thread is mixed all around and begins to strangle you.', 'As you are strangled you see who set this trap. (What else could it be, with all this thread everywhere?) It is こういち, who just watches you as you lose consciousness, tapping his fingers together.', NULL),
  ('00000000-0000-4000-8000-000000001276', 'kanji', '輩', '輩', 25, 36, 'The criminal that stole your car was your comrade! You thought the two of you were friends, but you were probably wrong.', 'You feel really weird about this whole situation so you write your comrade a haiku (はい). It''s really all you can do, since your car is long gone.', NULL),
  ('00000000-0000-4000-8000-000000001277', 'kanji', '隠', '隠', 25, 37, 'Behind a building, a cleat-wearing wolverine is holding his heart and trying to hide.', 'The wolverine looks up at the building he''s trying to hide behind and sees it''s an inn (いん).', NULL),
  ('00000000-0000-4000-8000-000000001278', 'kanji', '掛', '掛', 25, 38, 'Somebody got dirt on your fingers and dirt on your toes so you''re going to hang them upside-down and slap them with your dirty extremities.', 'You have this person hanging upside-down but they don''t seem to be suffering enough, so you hit them with your car (か). No mercy.', NULL),
  ('00000000-0000-4000-8000-000000001279', 'kanji', '替', '替', 25, 39, 'A husband marries a husband while the sun goes down and the men replace their solitary lives with one of everlasting companionship. Instead of one husband and one wife, we have two husbands here. They shed their lives of bachelorhood and replace it with one of monogamy.', 'After the ceremony, the husband and his husband get in a car (か) and drive off into the sunset. They’ll never be able to replace this memory with anything. Truly it is the happiest day of these husbands’ lives.', NULL),
  ('00000000-0000-4000-8000-000000001280', 'kanji', '居', '居', 25, 40, 'The flag is old but that doesn''t mean it''s not still alive. This is a living flag, and it gets old just like other living things.', 'The flag that is old and alive is actually a Buddhist relic (that''s why it''s alive, in fact ... and old!). But, it''s a really dumb relic, so it''s put in Little Kyoto (きょ).', NULL),
  ('00000000-0000-4000-8000-000000001281', 'kanji', '造', '造', 26, 5, '"A scooter!" you announce. You are announcing this because you decided this is what you would create.', 'But, a scooter has been created before. What is different about yours? The scooter you will create is specifically designed to keep zombies (ぞう) busy.', NULL),
  ('00000000-0000-4000-8000-000000001282', 'kanji', '授', '授', 26, 6, 'There are fingers reaching towards you asking you to accept to instruct them. They''re the fingers of students. And you''re the teacher. See them reach out for knowledge. They want to accept this knowledge into their hearts and brains. Instruct them!', '"Yes! I will instruct you, my dear students!" you cry, "I will instruct you on how to open a small juice (じゅ) box!" That''s right. These little kids need help learning how to open small juice boxes (small because kids are small).', NULL),
  ('00000000-0000-4000-8000-000000001283', 'kanji', '印', '印', 26, 7, 'You take this comb, break the handle off, and use it to stamp your official seal of approval onto a document. It''s kind of a messy marking process, but it gets the job done.', 'You need this seal to stay at an inn (いん). All inns require official paperwork, so you had to improvise and make a seal on the fly.', NULL),
  ('00000000-0000-4000-8000-000000001284', 'kanji', '創', '創', 26, 8, 'In your warehouse you use your knife to create. You keep old pieces of wood in your warehouse, and you use your knife to carve them into new things that only you could create.', 'When you create it''s good for your soul (そう). It''s so freeing, in fact, that when you get really into your creating, sometimes you''d swear your soul was floating a little bit outside of your body. But every time you notice, it sinks back down. Hmm.', NULL),
  ('00000000-0000-4000-8000-000000001285', 'kanji', '復', '復', 26, 9, 'You loiter around a black hole, waiting for it to finish destroying and switch to restore mode. You were told all black holes finish eventually, and when they do you can press a button to restore everything back to the way it was.', 'Finally there''s nothing else for the black hole to eat so you hit the restore button.... but nothing happens. "Oh f**k (ふく) you!" you scream as you realize you were lied to.', NULL),
  ('00000000-0000-4000-8000-000000001286', 'kanji', '往', '往', 26, 10, 'You loiter around your master until he departs on a journey. You have a lot more freedom to do things after your master has departed, so until that time you just loiter about looking busy and staying out of his way.', 'Finally, it''s time for your master''s journey and he calls to you and says, "You are the 王 (おう) of the house now. Take care of everything while I''m gone."', NULL),
  ('00000000-0000-4000-8000-000000001287', 'kanji', '較', '較', 26, 11, 'Your new car doesn’t mix well with the other cars in your garage because its color is in stark contrast to the others. All of your other cars are pristine white in color, but this new car is a mix of lots of colors. It almost looks like a peacock or something it’s so colorful. Such a contrast.', 'What did I say this car looks like? Oh that’s right, a peacock (かく). This car looks like a peacock. It’s the color of a peacock and you’ll look like you’re peacocking when you’re out on the town driving it. It really is such a stark contrast to like, every other car out there.', NULL),
  ('00000000-0000-4000-8000-000000001288', 'kanji', '筆', '筆', 26, 12, 'Out of bamboo, you make a brush – a writing brush. This is no ordinary brush, mind you. It is a brush specifically designed for writing elegant characters. And it’s made from bamboo!', 'Once the writing brush hits (ひつ) that paper, it’s like you transform into a totally different person. All of a sudden you’re a master calligrapher, writing anything and everything in a most beautiful fashion. Once that brush hits the paper, it’s on!', NULL),
  ('00000000-0000-4000-8000-000000001289', 'kanji', '鉛', '鉛', 26, 13, 'You hold gold fins in your mouth while shopping for pencil lead at the store. This pencil lead store only accepts gold fins as payment, but your fins don’t fit in your pockets and you need your hands to carry the lead so the gold fins go in your mouth.', 'You pay for your lead but the cashier puts it in your mouth where the gold fins were and... everything ends (えん).', NULL),
  ('00000000-0000-4000-8000-000000001290', 'kanji', '貯', '貯', 26, 14, 'You keep all of your shellfish under a roof down the street and it''s your savings. Shellfish used to be used as money way back, and these aren''t shellfish you''re spending, they''re ones you''re saving up for later.', 'When you want to withdraw from your savings you force yourself to use chopsticks (ちょ) to pick up the shellfish. They''re especially slippery, hard to use chopsticks too, that way it''s really hard to take too much out of your savings.', NULL),
  ('00000000-0000-4000-8000-000000001291', 'kanji', '故', '故', 26, 15, 'The old winter is to blame for today''s circumstance. It is the reason things are bad now.', 'In reality, this circumstance was actually caused by a single 子 (こ), though. This kid went through town, destroying everything in their path.', NULL),
  ('00000000-0000-4000-8000-000000001292', 'kanji', '障', '障', 26, 16, 'There''s a building standing in the way of the next chapter in your life, and it''s hindering you. It''s not like you couldn''t find another way around, but it''s definitely inconvenient.', 'Someone put this building here specifically to hinder you. They knew you were close to the next chapter of your life, and they wanted to hinder you really good. And there they are, sitting on a throne smirking. It''s the Shougun (しょう).', NULL),
  ('00000000-0000-4000-8000-000000001293', 'kanji', '従', '従', 26, 17, 'If you see someone loitering around with horns on their head you''d be correct to obey and accompany them.', 'If you obey the horned man you''ll end up with a ton of jewels (じゅう)!', NULL),
  ('00000000-0000-4000-8000-000000001294', 'kanji', '我', '我', 26, 18, 'Your ego... it''s totally out of control. I mean, my ego isn''t out of control. I''m the greatest. That''s me. But your ego? Ugh, so out of control unlike my amazing ego.', 'I am the greatest in the world! I am no baby like you, that''s why. A baby who says "ga (が) ga ga ga!"', NULL),
  ('00000000-0000-4000-8000-000000001295', 'kanji', '激', '激', 26, 19, 'A tsunami that is white, traveling in the direction of winter is a fierce and violent force of nature. This white tsunami is chasing after winter, and that’s why the tsunami is white—it’s a winter tsunami. It’s the most fierce and most violent kind of tsunami in existence.', 'The tsunami is too fierce, too violent, and before you realize what''s happening, Gecki (げき), your beloved gecko, is lifted up and carried off into the air.', NULL),
  ('00000000-0000-4000-8000-000000001296', 'kanji', '刺', '刺', 26, 20, 'There is a head pinned to a tree by a knife. This person has been stabbed! They were stabbed so hard that they were pinned to the tree here.', 'You want to know who did the stabbing, so you look around to see if the stabber is still in the area. But all you see is a sheep (し). Sheep can''t stab people, right? They have hooves and probably can''t pick up knives... right?', NULL),
  ('00000000-0000-4000-8000-000000001297', 'kanji', '励', '励', 26, 21, 'The "Cliff of Ten Thousand Power" is where you go if you want to be encouraged.', 'When you get there, it does encourage you. The cliff says "Hey, I encourage you to buy a ray (れい) gun."', NULL),
  ('00000000-0000-4000-8000-000000001298', 'kanji', '討', '討', 26, 22, 'They say using a measurement device (like a ruler) is a good way to chastise someone. They do something bad? Chastise them by slapping their wrists, their feet, their eyes, ears, anything! They say something out of turn? CHASTISE THEM!', 'You''re being chastised because you tried to say something in English in とうきょう. Everyone around you slowly turned around, eyes aflame and rulers in hand, ready to chastise you for uttering those forbidden words.', NULL),
  ('00000000-0000-4000-8000-000000001299', 'kanji', '郵', '郵', 26, 23, 'A broken car sits in a building. You need to get rid of it, so you put it in the mail. Or, depending on where you live, maybe you put it in the post.', 'Who did you address this broken car mail (or post) to? You sent it to the youths (ゆう) of the world.', NULL),
  ('00000000-0000-4000-8000-000000001300', 'kanji', '針', '針', 26, 24, 'In a gold cross, you see a needle sticking out of it. The needle is right in the middle of the gold cross. If Jesus were on there, the needle would be sticking him right in the chest.', 'You''re about to give up on the needle when it pops out and flies directly into your shin (しん). Ouch! Now you''re desperately trying to pull the needle out of your shin, but it really won''t budge this time. Maybe you should have minded your own business.', NULL),
  ('00000000-0000-4000-8000-000000001301', 'kanji', '徴', '徴', 26, 25, 'A loitering mountain king in the winter is an indication or sign of something to come.', 'When you spot a loitering mountain king in the winter, you know it''s an indication that soon Mrs. Chou (ちょう) will appear. It''s like a Groundhog''s Day kind of situation, but instead it means Mrs. Chou is about to come out, perhaps early for the season.', NULL),
  ('00000000-0000-4000-8000-000000001302', 'kanji', '怪', '怪', 26, 26, 'You see a soul floating around a tombstone acting suspicious. To be fair, if a soul is going to be anywhere, a tombstone is probably high up on the list, but this one seems like it''s doing something weird.', 'You sneak around the tombstone to see what this suspicious soul is doing, and you realize it''s pretending to kayak (かい). The soul is sitting behind the tombstone, in a small kayak, moving its arms like it''s rowing through water.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000004393', 'vocabulary', '続ける', '続ける', 21, 54, 'Ini seperti 続く kecuali sekarang kaulah yang melanjutkan. Sayangnya, tidak ada cara yang baik untuk membedakan kedua "lanjutan" hanya dengan menggunakan maknanya saja, namun Anda dapat memikirkannya seperti ini: Dengan ける, Anda benar-benar peduli untuk melanjutkan hal ini sehingga Anda melanjutkannya (melakukan tindakan melanjutkan). Dengan く kamu hanya bilang "tidak apa-apa jika terus berlanjut, tapi aku tidak terlalu peduli...', 'The reading is the same as 続く, so be sure to know that so you can know this.', NULL),
  ('00000000-0000-4000-8000-000000004394', 'vocabulary', '固有名詞', '固有名詞', 21, 55, 'Kata benda (名詞) yang mempunyai kekerasan adalah kata benda yang tidak dapat digerakkan. Itu adalah kata benda yang besar, sangat besar sehingga Anda harus menggunakan huruf kapital untuk kata benda semacam ini dalam bahasa Inggris. Itu adalah kata benda yang tepat.', 'This is a jukugo word, which usually means on''yomi readings from the kanji. If you know the readings of your kanji you''ll know how to read this as well. It will help to know the word 名詞 as well.', NULL),
  ('00000000-0000-4000-8000-000000004395', 'vocabulary', '保守主義', '保守主義', 23, 39, 'Anda tahu bahwa 主義 adalah "-isme." Tambahkan paham tersebut kepada orang-orang yang ingin melindungi dan melestarikan negaranya agar tetap seperti apa adanya (selamanya). Itu konservatisme dan mereka adalah orang-orang konservatif.', 'This word uses the reading of 保守的 for the first half and then the regular kanji readings for the second half. Combine those things and you''ll be a master of righteousness and / or kanji.', NULL),
  ('00000000-0000-4000-8000-000000004396', 'vocabulary', '他動詞', '他動詞', 21, 56, 'Ingat bagaimana 自動詞 adalah "kata kerja intransitif"? Kata kerja intransitif adalah ketika sesuatu terjadi begitu saja. Anda tidak melakukan tindakan terhadap mereka. Namun kata ini adalah jenis yang lain. Kata kerja transitif adalah ketika Anda melakukan sesuatu secara langsung terhadap hal lain. Itu sebabnya ada kata lain di sana, karena itu adalah kata kerja (動詞) yang Anda lakukan pada hal lain, secara langsung.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004397', 'vocabulary', '暴力団', '暴力団', 21, 57, 'Kelompok yang mempunyai kekuasaan dengan menggunakan kekerasan? Kedengarannya seperti sindikat kejahatan bagi saya, mungkin Yakuza atau organisasi gangster lainnya.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004398', 'vocabulary', '容疑者', '容疑者', 21, 58, 'Aku punya kecurigaan (容疑) tentang seseorang. Seseorang itu adalah tersangka utamaku.', 'This is a jukugo word, which usually means on''yomi readings from the kanji. If you know the readings of your kanji you''ll know how to read this as well. Will help to be able to read 容疑 first, though.', NULL),
  ('00000000-0000-4000-8000-000000004399', 'vocabulary', '暴走族', '暴走族', 21, 59, 'Suku yang menjadi liar (暴走) disebut oleh orang Jepang sebagai geng pengendara motor. Bayangkan saja mereka berkeliling dengan sepeda, berlari liar. Mereka juga dekat, seperti keluarga. Bagus sekali!', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004400', 'vocabulary', '経済', '経済', 21, 60, 'Ketika perjalanan waktu berakhir, Anda melihatnya kembali dan melihat seberapa baik Anda melakukannya. Apakah kita menghasilkan lebih banyak uang? Apakah penghasilan kita lebih sedikit? Itu semua ekonomi, sayang (itu uang, sayang!).', 'This is a jukugo word, which usually means on''yomi readings from the kanji. If you know the readings of your kanji you''ll know how to read this as well. The さい changes to ざい, though, so watch out for that.', NULL),
  ('00000000-0000-4000-8000-000000004401', 'vocabulary', 'いい加減にしろ', 'いい加減にしろ', 21, 61, 'Anda tahu bagaimana いい加減 tidak berdasar atau tidak ada gunanya? Karena kalau ditambah lalu dikurangi sebenarnya belum berbuat apa-apa? Ini seperti mengatakan "lakukan hal yang tidak ada gunanya!" Oke, itu tidak masuk akal. Ini adalah ungkapan yang artinya mirip dengan hentikan atau hentikan BS!', 'The reading is the same as いい加減, which you (hopefully) learned earlier.', NULL),
  ('00000000-0000-4000-8000-000000004402', 'vocabulary', '手続き', '手続き', 21, 62, 'Seseorang memegang tanganmu dan menunjukkan kepadamu cara untuk melanjutkan. "Ini prosedurnya," kata mereka. Gerakkan tanganmu seperti ini. Bagus sekali. Prosedur yang bagus. Bagus!', 'The reading is the kun''yomi vocab readings of 手 and 続く put together into one. Darn these body parts making everything kun''yomi.', NULL),
  ('00000000-0000-4000-8000-000000004403', 'vocabulary', '敵', '敵', 21, 63, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'The reading is the same as what you learned with the kanji. No enemies here!', NULL),
  ('00000000-0000-4000-8000-000000004404', 'vocabulary', '素敵', '素敵', 21, 64, 'Unsur musuh bukanlah sesuatu yang harus dianggap buruk. Anda harus memiliki "elemen musuh" jika Anda ingin memiliki hal-hal yang indah, melamun, dan indah juga. Ini adalah kata yang bagus ketika Anda berbicara tentang pria yang menurut Anda tidak sopan. Tidak bekerja dengan baik pada perempuan.', 'This is a jukugo word, which usually means on''yomi readings from the kanji. You haven''t learned this reading for 素 yet, so here''s a mnemonic to help you:
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000004593', 'vocabulary', '革命', '革命', 23, 57, 'Nasib Leather ada di tangan revolusi. Ini adalah revolusi kulit! Kenakan pakaian biasa ini dan kenakan pakaian kulit!', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004594', 'vocabulary', '皮革', '皮革', 23, 58, 'Kulit kulit sebenarnya hanyalah kulit karena kulit juga kulit. Itu juga menyembunyikan.', 'The reading is the on''yomi readings of the kanji. You should know them both already!', NULL),
  ('00000000-0000-4000-8000-000000004595', 'vocabulary', '無職', '無職', 23, 59, 'Bila status pekerjaan Anda “tidak ada” maka kemungkinan besar Anda menganggur. Anda mengalami pengangguran.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004596', 'vocabulary', '職場', '職場', 23, 60, 'Lokasi kerja Anda adalah tempat Anda bekerja atau tempat kerja Anda. Itu juga tempat kerja Anda.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000004793', 'vocabulary', '候補者', '候補者', 25, 80, 'Kandidat adalah seseorang yang merupakan pelengkap dari keseluruhan sistem politik. Meski hanya pelengkap, mereka tetaplah kandidat, kecuali mereka bisa menang!', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004794', 'vocabulary', '気候', '気候', 25, 81, 'Energi iklim adalah iklim. Energi tinggi? Iklim. Energi rendah. Iklim.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004795', 'vocabulary', '天候', '天候', 25, 82, 'Iklim surga adalah cuacanya.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004796', 'vocabulary', '時候', '時候', 25, 83, 'Iklim saat ini adalah musim saat ini. Setiap musim memiliki cuaca yang berbeda dan terjadi pada waktu yang berbeda sepanjang tahun.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000005000', 'vocabulary', '腰抜け', '腰抜け', 27, 41, 'Jika Anda menarik pinggang Anda, Anda menarik tubuh Anda dari situasi tersebut dan mencoba melarikan diri. Sungguh pengecut. 
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000005200', 'vocabulary', '逆らう', '逆らう', 28, 134, 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berlawanan jadi versi verbanya adalah menentang atau melawan.', 'Since this word consists of a kanji with hiragana attached, you can bet that it will use the kun''yomi reading. You didn''t learn that reading with this kanji, so here''s a mnemonic to help you: 
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000005715', 'vocabulary', '了解', '了解', 23, 128, 'Ketika Anda telah selesai memecahkan sesuatu, Anda telah sampai pada titik pemahaman dan pemahaman. Juga, digunakan dalam komunikasi (seringkali radio) untuk menandakan Anda tahu apa yang terjadi. Ini seperti mengatakan "baiklah!"', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005716', 'vocabulary', '主', '主', 30, 128, 'Kata ini mempunyai arti yang mirip dengan <ja>主人</ja> (<vocabulary>kepala rumah tangga</vocabulary>). Anda juga dapat mengingatnya sesuai makna yang Anda pelajari dengan kanji <ja>主</ja>, yaitu <vocabulary>master</vocabulary>.', 'Pembacaannya tentu saja berbeda dengan yang Anda pelajari dengan kanji. Pikirkan ini:
